// ===== ランク基準ステータス =====
// モンスターランク (1-10) から基準ステータスを算出する。全100迷宮のバランスの
// 単一の調整点。個体差は mul (hp/atk などの倍率) で付ける。
// ・hp はプレイヤーの攻撃力カーブ (魂×5部位+武器) に対し通常2-3撃で倒せる量
// ・atk はプレイヤーの VIT 半減則 (combat.js) を踏まえた貫通量
export function monStats(rank, boss = false) {
  return rankStats(Math.min(10, rank), boss);
}
// monStats の上限 (rank10) を外した版。ミミックのように「その階の敵より数ランク上」を
// 組む個体が rank10 を超えても、同じ曲線のまま強くなるようにする。
export function rankStats(rank, boss = false) {
  const r = Math.max(1, rank);
  const s = {
    hp: Math.round(30 * Math.pow(r, 1.8)),
    atk: Math.round(12 + 3.2 * r * r),
    def: Math.round(2 * Math.pow(r, 1.5)),
    spd: 4 + Math.round(r * 0.9),
    soul: Math.round(10 * Math.pow(1.65, r - 1)),
    gold: Math.round(8 * Math.pow(1.7, r - 1)),
  };
  if (boss) {
    s.hp = Math.round(s.hp * 4.0);
    s.atk = Math.round(s.atk * 1.4);
    s.def = Math.round(s.def * 1.3);
    s.spd += 3;
    s.soul *= 8;
    s.gold *= 10;
  }
  return s;
}

// ===== モンスター定義ヘルパー =====
// すべてのモンスターはここを通る。スキーマ:
// { id, key, name, race, rank, desc, maxhp, hp, atk, def, spd, soul, gold,
//   art, palette, boss?, dropNormal?, dropRare?, soulClass? }
// soul は撃破時に回収できる Soul 量 (経験値の役割を兼ねる)。
// 注: def/spd は定義用の名前のまま。出現時に六大ステへ写像される
//     (combat.js makeEnemy: atk→ATK, def→VIT, spd→AGI)。
// dropNormal/dropRare は省略可 (省略時は game.js がランクから決定的に割り当てる)。
// soulClass を持つ人型は撃破時にまれに魂を落とす。
export function defMonster(def) {
  if (!def.id) throw new Error("monster id required");
  if (!ARTS[def.artKey || ""] && !def.art) throw new Error("unknown artKey: " + def.artKey + " (" + def.id + ")");
  const base = ARTS[def.artKey] || {};
  const m = {
    id: def.id, key: def.id,
    name: def.name || "???",
    race: def.race || "beast",
    element: def.element || "none",
    rank: def.rank || 1,
    desc: def.desc || "",
    maxhp: def.hp || 10, hp: def.hp || 10,
    atk: def.atk || 1, def: def.def || 0, spd: def.spd || 5,
    soul: def.soul || 5, gold: def.gold || 3,
    art: def.art || base.art,
    palette: def.palette || base.palette,
    boss: !!def.boss,
  };
  if (def.dropNormal) m.dropNormal = def.dropNormal;
  if (def.dropRare) m.dropRare = def.dropRare;
  if (def.soulClass) m.soulClass = def.soulClass;
  if (def.elite) m.elite = true; // 強敵 (強敵階専用。通常プール・ミミックの対象外)
  if (def.evOnly) m.evOnly = true; // 出来事の魔物 (events.js 専用。通常プールの対象外)
  // 役割持ち: role (healer/guard/summoner) + escort (取り巻きのid)。
  // summoner は summonKey の仲間を戦闘中に呼び寄せる。ability は明示指定で上書き可
  // (省略時は game.js が種族から決定的に付与する)
  if (def.role) m.role = def.role;
  if (def.escort) m.escort = def.escort;
  if (def.summonKey) m.summonKey = def.summonKey;
  if (def.ability !== undefined) m.ability = def.ability;
  // 個体ごとの戦闘特性 (図鑑にも掲載される):
  //   physResist : 物理抵抗値 0〜100 (値と同じ割合を軽減)
  //   magWeak    : 攻撃呪文の被ダメ倍率 (>1)。「魔法に弱い」表現
  //   regen      : 毎ラウンド最大HPの割合だけ自己回復 (0〜1)
  //   swift      : 出現時に AGI を底上げ (先手を取りやすい)
  //   evasive    : 物理攻撃を確率で大きく回避する
  //   pack       : 群れで現れる (出現数の下限を引き上げる)
  // 抵抗値は0〜100の整数に限る
  for (const k of ["physResist", "magResist"]) {
    if (def[k] != null && (!Number.isInteger(def[k]) || def[k] < 0 || def[k] > 100)) throw new Error(`${k} must be 0-100 (${def.id})`);
  }
  if (def.physResist >= 100 && def.magResist >= 100) throw new Error(`物理・魔法の両方を無効にできない (${def.id})`);
  if (def.physResist) m.physResist = def.physResist;
  if (def.magWeak) m.magWeak = def.magWeak;
  if (def.regen) m.regen = def.regen;
  if (def.swift) m.swift = true;
  if (def.evasive) m.evasive = true;
  if (def.pack) m.pack = true;
  // 追加の戦闘特性 (combat.js が解釈):
  //   magResist   : 魔法抵抗値 0〜100 (値と同じ割合を軽減)
  //   enrage      : HPが3割を切ると一度だけ ATK/AGI が跳ね上がる
  //   endure      : 致死の一撃を一度だけ HP1 で耐える
  //   lifesteal   : 与えた物理ダメージの割合だけ自己回復 (0〜1)
  //   multistrike : 1手番で続けざまに攻撃する回数 (2〜4)
  //   barrier     : 被ダメを半減できる残り回数 (数回制)
  //   (ability に "warcry"=鼓舞 / "weaken"=弱体 / "sleep"=眠り / "charm"=魅了 / "confuse"=混乱 も指定可)
  //   (ability に "charge"=溜め (予兆の後に大技) / "sunder"=守り崩し (VIT −1段) / "dispel"=打ち消し (隊の強化を剥ぐ) も指定可)
  if (def.magResist) m.magResist = def.magResist;
  if (def.enrage) m.enrage = true;
  if (def.endure) m.endure = true;
  if (def.lifesteal) m.lifesteal = def.lifesteal;
  if (def.multistrike) m.multistrike = def.multistrike;
  if (def.barrier) m.barrier = def.barrier;
  // 第5層からの「特色を極端に押し出す」ための特性:
  //   haste  : 神速。AGI を大きく底上げし、1ラウンドに2度動く (ラウンドの頭ともう一度)
  //   abRate : 特殊能力 (ability) を使う確率 (0〜0.6)。既定は 25% (ブレス・全体呪文は 30%)。0.4 以上は図鑑で「多用」と示す
  //   (ability に "spell"=全体呪文 (固有属性の呪文で隊全体を撃つ) も指定可)
  if (def.haste) m.haste = true;
  if (def.abRate != null) {
    if (!(def.abRate > 0 && def.abRate <= 0.6)) throw new Error(`abRate must be 0-0.6: ${def.abRate} (${def.id})`);
    if (!def.ability) throw new Error(`abRate needs an ability (${def.id})`);
    m.abRate = def.abRate;
  }
  // 金属の魔物 (METAL_TIERS の段 1〜3)。出現表には入らず、game.js が稀に盤面へ紛れ込ませる
  if (def.metal != null) {
    if (!METAL_TIERS[def.metal]) throw new Error(`metal must be tier 1-3: ${def.metal} (${def.id})`);
    m.metal = def.metal;
  }
  if (def.traits) m.traits = def.traits; // 表示専用の追加特徴キー
  m.resistOverrides = { ...(def.resists || {}) };
  m.resists = monsterResists({ ...m, resists: m.resistOverrides });
  m.physResist = m.resists.physResist; m.magResist = m.resists.magResist;
  return m;
}

// ===== モンスターの特徴・スキル (図鑑表示 + 戦闘挙動の単一の語彙) =====
// 各キーは「ラベル」と「説明」を持つ。固有ドロップに代わって図鑑に列挙される。
export const TRAITS = {
  swift:      { label: "俊敏",   desc: "素早く先手を取りやすい" },
  evasive:    { label: "回避",   desc: "物理攻撃をよくかわす" },
  physResist: { label: "物理抵抗値", desc: "物理が効きにくい" },   // 実際の表記は抵抗値で変わる (monsterTraits)
  magWeak:    { label: "魔法弱点", desc: "魔法で大ダメージを受ける" },
  regen:      { label: "再生",   desc: "毎ターン少しずつ傷を癒す" },
  pack:       { label: "群棲",   desc: "群れをなして現れる" },
  summon:     { label: "招来",   desc: "戦闘中に仲間を呼び寄せる" },
  heal:       { label: "治癒",   desc: "傷ついた仲間を癒す" },
  guard:      { label: "護衛",   desc: "仲間への攻撃をかばう" },
  breath:     { label: "ブレス", desc: "全体を巻き込む息を吐く" },
  poison:     { label: "毒",     desc: "攻撃で毒を与えてくる" },
  paralyze:   { label: "麻痺",   desc: "攻撃で麻痺させてくる" },
  stone:      { label: "石化",   desc: "凝視で石に変えてくる" },
  drain:      { label: "吸命",   desc: "宿した魂のレベルを喰らう" },
  soulSteal:  { label: "魂奪",   desc: "Soul を吸い取ってくる" },
  goldSteal:  { label: "強奪",   desc: "金品を奪い取ってくる" },
  critical:   { label: "痛撃",   desc: "急所を狙う一撃を放つ" },
  magResist:  { label: "魔法抵抗値", desc: "魔法が効きにくい" },   // 同上
  enrage:     { label: "激昂",   desc: "手負いになると荒れ狂う" },
  endure:     { label: "不屈",   desc: "致命の一撃を一度だけ耐える" },
  lifesteal:  { label: "吸血",   desc: "与えた傷の分だけ己を癒す" },
  multistrike:{ label: "連撃",   desc: "一手で続けざまに打つ" },
  barrier:    { label: "障壁",   desc: "数度だけ被害を半減する" },
  warcry:     { label: "鼓舞",   desc: "雄叫びで味方を奮い立たせる" },
  weaken:     { label: "弱体",   desc: "力を削ぐ呪いをかける" },
  sleep:      { label: "眠り",   desc: "眠りを誘う息で隊を眠らせてくる" },
  charm:      { label: "魅了",   desc: "心を奪い、仲間に襲いかからせてくる" },
  confuse:    { label: "混乱",   desc: "惑わせて、敵味方の見境をなくさせる" },
  haste:      { label: "神速",   desc: "目にも止まらぬ速さで、1ターンに2度動く。逃げるのも難しい" },
  spell:      { label: "全体呪文", desc: "呪文で隊全体を撃つ (精神の強さで少し軽減)" },
  metal:      { label: "金属の体", desc: "呪文・状態異常・弱体が効かず、ダメージは1しか通らない。会心の一撃だけは素通しになる" },
  fleet:      { label: "逃げ足", desc: "隙あらば逃げ出す。倒せば莫大な✦Soulを残す" },
  charge:     { label: "溜め",   desc: "力を溜めて予兆を見せ、次の手番で大技を放つ。封じ・眠り・麻痺・打ち消しで溜めを潰せる" },
  sunder:     { label: "守り崩し", desc: "鎧ごと打ち砕き、守り (VIT) を1段下げてくる" },
  dispel:     { label: "打ち消し", desc: "隊の強化や構えが厚くなると、禍言でまとめて剥ぎ取ってくる" },
  shake:      { label: "払いのけ", desc: "弱体が深くなると身を震わせて振り払う。弱体は −2段までしか入らない" },
};
// 特殊能力を多用する魔物 (abRate がこれ以上) は、図鑑の札に「多用」と添える
export const AB_RATE_HEAVY = 0.4;

// モンスター定義から特徴キーの並びを導く (重複なし、表示順は定義順)。
// 既存の ability / role と新フィールドを単一の語彙へ正規化する。
// 宙に浮く魔物か (戦闘待機中・図鑑で上下にゆらめかせるのはこれだけ。地に足の着いた者は揺らさない)
// 種族で決まるもの: 飛獣/鳥人/幽鬼/精霊。それ以外の種族でもはねや翼で飛ぶ個体は ID で個別に指定する。
const FLOAT_RACES = new Set(["wing", "avian", "specter", "elemental"]);
const FLOAT_IDS = new Set([
  "bat", "wraith", "cm_bat", "d02_imp", "d03_ghost",
  "bs_bloatfly", "bs_giantmoth", "bs_emberswarm", "bs_blightmoth", "bs_windscythe", "bs_sparkswarm", "bs_emberfly", "bs_lightmoth",
  "bs_familiarswarm", "bs_fallenangel", "bs_cyclonedjinn",
  "bs_wyvern", "bs_stormwyvern", "bs_wyvernlord", "bs_skydrake", "bs_wingedterror",
]);
// 幽鬼に分類されていても生身の者 (浮かない)
const GROUNDED_IDS = new Set(["bs_cultist", "bs_stonegorgon"]);
export function isFloating(m, key) {
  if (!m) return false;
  const id = key || m.key || m.id || "";
  if (GROUNDED_IDS.has(id)) return false;
  return FLOAT_IDS.has(id) || FLOAT_RACES.has(m.race);
}

export function monsterTraitKeys(m) {
  if (!m) return [];
  const keys = [];
  const add = (k) => { if (k && TRAITS[k] && !keys.includes(k)) keys.push(k); };
  if (m.metal) { add("metal"); add("fleet"); add("evasive"); }
  if (m.haste) add("haste");
  if (m.swift) add("swift");
  if (m.evasive) add("evasive");
  if (m.physResist) add("physResist");
  if (m.magWeak) add("magWeak");
  if (m.regen) add("regen");
  if (m.pack) add("pack");
  if (m.magResist) add("magResist");
  if (m.enrage) add("enrage");
  if (m.endure) add("endure");
  if (m.lifesteal) add("lifesteal");
  if (m.multistrike) add("multistrike");
  if (m.barrier) add("barrier");
  if (m.role === "summoner") add("summon");
  if (m.role === "healer") add("heal");
  if (m.role === "guard") add("guard");
  add(m.ability); // poison/paralyze/stone/drain/soulSteal/goldSteal/critical/breath/spell/warcry/weaken/sleep/charm/confuse/charge/sunder/dispel
  // 主・精鋭は誰でも大技を溜め (combat.js の予兆)、深い弱体を払いのける
  if ((m.boss || m.elite) && !m.metal) { add("charge"); add("shake"); }
  for (const t of m.traits || []) add(t);
  return keys;
}

// 表示用に {key,label,desc} の配列へ展開する
// 物理・魔法は抵抗値と軽減率を表示する
export function monsterTraits(m) {
  return monsterTraitKeys(m).map((k) => {
    if (["physResist", "magResist"].includes(k) && m[k]) {
      const r = m[k];
      return { key: k, label: `${k === "physResist" ? "物理" : "魔法"}抵抗値 ${r}`, desc: r === 100 ? "無効" : `${r}%軽減` };
    }
    // 特殊能力を多用する個体: 札に「多用」を添える
    if (k === m.ability && m.abRate >= AB_RATE_HEAVY) return { key: k, label: `${TRAITS[k].label}・多用`, desc: `${TRAITS[k].desc} (頻繁に使う)` };
    return { key: k, ...TRAITS[k] };
  });
}

// 定義の配列を { id: monster } に変換 (重複IDは即エラー)
export function defMonsters(defs) {
  const out = {};
  for (const d of defs) {
    const m = defMonster(d);
    if (out[m.id]) throw new Error("duplicate monster id: " + m.id);
    out[m.id] = m;
  }
  return out;
}
